//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS05700.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 신규/변경 접수 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    if ($c.stf.compareFromToDate2(edt_pISUR_APPL_SDD, edt_pISUR_APPL_EDD) == false) {
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05700_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpIssInstPrcListView" + "&{P}ISUR_APPL_SDD=" + edt_pISUR_APPL_SDD.getValue() + "&{P}ISUR_APPL_EDD=" + edt_pISUR_APPL_EDD.getValue() + "&{P}ISUR_APPL_TP_CD=" + $c.stf.getObjectValue(cmb_pISUR_APPL_TP_CD) + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() +
        //"&{P}ISUR_NM=" +  txb_pISUR_NM.value +
        "&{P}PROC=" + $c.stf.getObjectValue(cmb_pPROC);
    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    //	arrPar[1] = txb_param2.value; // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.gform_onload = function() {
    ins_combo_set(dts_ISUR_APPL_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03433", "ALL"); // 03433 - 신청구분  
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.fn_setFromToDate(1, edt_pISUR_APPL_SDD, edt_pISUR_APPL_EDD);
    edt_pISUR_APPL_SDD.focus();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_ISUR_APPL_SDD_onclick = function() {
    popUpCalendar2(edt_pISUR_APPL_SDD);
};
scwin.img_ISUR_APPL_EDD_onclick = function() {
    popUpCalendar2(edt_pISUR_APPL_EDD);
};
scwin.dts_ISUR_APPL_TP_CD_OnLoadCompleted = function(rowcount) {
    cmb_pISUR_APPL_TP_CD.setSelectedIndex(0);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    txb_param1.setValue("");
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row == 0) return;
    txb_param1.setValue(dts_List.getCellData(row, "ISUR_APPL_ID"));
    //txb_param2.value = dts_List.NameValue(row,"ISUR_NM"); 
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91700", "발행기관 신청 상세정보", "1240", "530");
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.cmb_pISUR_APPL_TP_CD_OnSelChange = function() {
    scwin.ins_search();
};
scwin.cmb_pPROC_OnSelChange = function() {
    scwin.ins_search();
};
